import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    jumps = 0
    cur_end = 0
    far = 0
    for i in range(n - 1):
        if i > far:
            print(-1)
            return
        far = max(far, i + a[i])
        if i == cur_end:
            jumps += 1
            cur_end = far
            if cur_end >= n - 1:
                break
    if n > 1 and far < n - 1:
        print(-1)
    else:
        print(jumps)

